<template>
  <PageHeader title="动物档案" :subtitle="role==='ADMIN'?'全部动物管理':'我负责的动物'"><el-button :loading="pager.loading.value" @click="load">刷新</el-button></PageHeader>
  <div class="toolbar"><el-select v-model="status" clearable placeholder="全部状态" style="width:190px" @change="search"><el-option v-for="s in statuses" :key="s" :label="displayText(s)" :value="s"/></el-select><el-input v-if="role==='ADMIN'" v-model="species" class="search-field" clearable maxlength="50" placeholder="动物种类" aria-label="按动物种类筛选" @keyup.enter="search"/><el-input v-if="role==='ADMIN'" v-model="rescueTaskId" class="search-field" clearable placeholder="救助任务编号" aria-label="按救助任务编号筛选动物" @keyup.enter="search"/><el-button v-if="role==='ADMIN'" type="primary" @click="search">查询</el-button><el-button v-if="role==='ADMIN'" @click="resetFilters">重置</el-button></div>
  <ListError :message="pager.error.value" @retry="load"/>
  <div class="card table-card"><el-table :data="pager.rows.value" v-loading="pager.loading.value" row-key="id" empty-text="暂无动物档案"><el-table-column prop="id" label="编号" width="90"/><el-table-column label="动物档案" min-width="280"><template #default="{row}"><div class="archive-row"><AuthImage class="archive-img" :src="row.coverImageUrl" fallback="/assets/pudding-cat-hero.png"/><div><b>{{row.name}}</b><div class="muted">{{displayText(row.species)}} · {{displayText(row.sex)}}</div></div></div></template></el-table-column><el-table-column prop="healthCondition" label="健康摘要" min-width="200" show-overflow-tooltip/><el-table-column label="状态" width="150"><template #default="{row}"><StatusBadge :value="row.status"/></template></el-table-column><el-table-column label="操作" width="170" fixed="right"><template #default="{row}"><el-button size="small" @click="open(row)">管理档案</el-button></template></el-table-column></el-table></div>
  <el-pagination class="pager" background layout="sizes,prev,pager,next,total" :page-sizes="[10,20,50]" :total="pager.total.value" v-model:page-size="pager.size.value" v-model:current-page="pager.page.value" @size-change="changePageSize" @current-change="load"/>
  <el-dialog align-center destroy-on-close :close-on-click-modal="false" v-model="drawer" width="900px" title="动物档案管理"><div v-loading="detailLoading"><template v-if="detail"><div class="archive-row"><AuthImage class="archive-img" :src="detail.images?.[0]?.url" fallback="/assets/pudding-cat-hero.png"/><div><h3 style="margin:0">{{detail.name}} #{{detail.id}}</h3><StatusBadge :value="detail.status"/></div></div><el-tabs style="margin-top:18px"><el-tab-pane label="基本资料"><el-form label-position="top"><div class="form-grid"><el-form-item label="名称" :error="errors.name"><el-input v-model="edit.name" maxlength="100" show-word-limit/></el-form-item><el-form-item label="种类" :error="errors.species"><el-input v-model="edit.species" maxlength="50"/></el-form-item><el-form-item label="性别"><el-select v-model="edit.sex" style="width:100%"><el-option v-for="x in ['MALE','FEMALE','UNKNOWN']" :key="x" :label="displayText(x)" :value="x"/></el-select></el-form-item><el-form-item label="估算年龄（月）"><el-input-number v-model="edit.estimatedAgeMonths" :min="0" :max="65535" style="width:100%"/></el-form-item><el-form-item label="毛色"><el-input v-model="edit.color" maxlength="100"/></el-form-item><el-form-item label="健康摘要" :error="errors.healthCondition"><el-input v-model="edit.healthCondition" maxlength="1000"/></el-form-item><el-form-item class="full" label="性格与行为观察"><el-input v-model="edit.personality" type="textarea" maxlength="1000" show-word-limit :rows="3" placeholder="例如：对陌生人需要适应，熟悉后亲人；对其他动物的接受程度"/></el-form-item><el-form-item class="full" label="领养家庭要求"><el-input v-model="edit.adoptionRequirements" type="textarea" maxlength="1000" show-word-limit :rows="3" placeholder="例如：室内喂养、安装纱窗、接受回访、运动和医疗要求"/></el-form-item></div><div class="action-row"><el-button type="primary" :loading="saving" @click="saveBasic">保存基本资料</el-button></div></el-form></el-tab-pane><el-tab-pane label="图片"><ImageTokenUploader v-model="newImageTokens"/><el-button type="primary" style="margin-top:10px" :loading="saving" :disabled="!newImageTokens.length" @click="appendImages">追加图片</el-button><div class="photo-list"><div v-for="img in detail.images||[]" :key="img.id" class="photo-item"><AuthImage :src="img.url"/><el-button type="danger" text :disabled="saving" @click="deleteImage(img)">删除</el-button></div></div></el-tab-pane><el-tab-pane label="健康记录"><div v-if="!health.length" class="muted">暂无健康记录</div><div v-for="h in health" :key="h.id" class="reason" style="margin-bottom:8px">{{h.content}}<div class="muted">{{h.createdAt}}</div></div><el-input v-model="healthText" type="textarea" maxlength="2000" show-word-limit placeholder="追加健康记录"/><el-button style="margin-top:8px" :loading="saving" @click="addHealth">追加健康记录</el-button></el-tab-pane><el-tab-pane label="状态操作"><div class="reason">领养申请获批后，系统会自动更新为“已领养”。</div><div class="action-row" style="margin-top:14px"><el-button v-if="detail.status==='TREATING'" :loading="saving" @click="stateAction('TO_OBSERVING')">进入观察</el-button><el-button v-if="detail.status==='OBSERVING'" type="primary" :loading="saving" @click="stateAction('OPEN_ADOPTION')">开放领养</el-button><el-button v-if="detail.status==='AVAILABLE'" type="warning" :loading="saving" @click="suspend">暂停领养</el-button><el-button v-if="detail.status==='SUSPENDED'" type="primary" :loading="saving" @click="stateAction('RESUME_ADOPTION')">恢复领养</el-button></div></el-tab-pane><el-tab-pane v-if="role==='RESCUER'" label="领养概览"><div v-loading="overviewLoading"><ListError :message="overviewError" @retry="loadOverview"/><template v-if="overview"><el-descriptions :column="1" border><el-descriptions-item label="动物状态"><StatusBadge :value="overview.animalStatus"/></el-descriptions-item><el-descriptions-item label="待审核申请">{{overview.pendingApplicationCount}}</el-descriptions-item><el-descriptions-item label="已批准申请">{{overview.approvedApplicationId||'—'}}</el-descriptions-item><el-descriptions-item label="领养记录">{{overview.adoptionRecordId||'—'}}</el-descriptions-item><el-descriptions-item label="领养时间">{{overview.adoptedAt||'—'}}</el-descriptions-item></el-descriptions><div class="reason" style="margin-top:12px">仅展示数量和记录标识，不展示其他申请人的理由、住房、家庭、养宠经验和联系方式。</div></template></div></el-tab-pane></el-tabs></template></div></el-dialog>
</template>
<script setup>
import {useRoute} from 'vue-router'
const route=useRoute()
import {ref,reactive,computed,onMounted} from 'vue';import {ElMessage} from '../plugins/message.js';import {ElMessageBox} from '../plugins/messageBox.js';import PageHeader from '../components/PageHeader.vue';import StatusBadge from '../components/StatusBadge.vue';import ImageTokenUploader from '../components/ImageTokenUploader.vue';import AuthImage from '../components/AuthImage.vue';import ListError from '../components/ListError.vue';import {animalApi,adminApi,adoptionApi} from '../api/index.js';import {useAuth} from '../store/auth.js';import {usePagination} from '../composables/usePagination.js';import {displayText} from '../utils/displayText.js'
const role=computed(()=>useAuth().state.user?.roleCode);const statuses=['TREATING','OBSERVING','AVAILABLE','SUSPENDED','ADOPTED'];const status=ref(statuses.includes(String(route.query.status))?String(route.query.status):''),species=ref(''),rescueTaskId=ref(''),pager=usePagination({pageSize:20}),drawer=ref(false),detail=ref(null),health=ref([]),overview=ref(null),overviewError=ref(''),newImageTokens=ref([]),healthText=ref(''),detailLoading=ref(false),overviewLoading=ref(false),saving=ref(false);const edit=reactive({name:'',species:'',sex:'UNKNOWN',estimatedAgeMonths:null,color:'',healthCondition:'',personality:'',adoptionRequirements:''}),errors=reactive({name:'',species:'',healthCondition:''})
async function load(){await pager.load(({page,size})=>{const params={page,size,...(status.value?{status:status.value}:{}),...(species.value.trim()?{species:species.value.trim()}:{}),...(rescueTaskId.value?{rescueTaskId:rescueTaskId.value}:{})};return role.value==='ADMIN'?adminApi.animals(params):animalApi.responsible(params)}).catch(()=>{})}
function search(){if(rescueTaskId.value&&!/^[1-9]\d*$/.test(rescueTaskId.value)){ElMessage.warning('请输入有效的正整数任务编号');return}pager.reset();load()}
function resetFilters(){status.value='';species.value='';rescueTaskId.value='';search()}function changePageSize(){pager.reset();load()}
function fill(){Object.assign(edit,{name:detail.value.name,species:detail.value.species,sex:detail.value.sex,estimatedAgeMonths:detail.value.estimatedAgeMonths??null,color:detail.value.color||'',healthCondition:detail.value.healthCondition,personality:detail.value.personality||'',adoptionRequirements:detail.value.adoptionRequirements||''})}
async function open(row){detailLoading.value=true;detail.value=null;drawer.value=true;overview.value=null;overviewError.value='';try{const [a,h]=await Promise.all([animalApi.detail(row.id),animalApi.health(row.id)]);detail.value=a;health.value=h;fill();newImageTokens.value=[];if(role.value==='RESCUER')loadOverview()}finally{detailLoading.value=false}}
async function loadOverview(){if(!detail.value)return;overviewLoading.value=true;overviewError.value='';try{overview.value=await adoptionApi.overview(detail.value.id)}catch(e){overviewError.value=e?.userMessage||'领养概览加载失败，请稍后重试'}finally{overviewLoading.value=false}}
async function refreshDetail(){detail.value=await animalApi.detail(detail.value.id);fill();health.value=await animalApi.health(detail.value.id)}
function validateBasic(){errors.name=edit.name.trim()&&edit.name.trim().length<=100?'':'名称必填且不能超过 100 字';errors.species=edit.species.trim()&&edit.species.trim().length<=50?'':'种类必填且不能超过 50 字';errors.healthCondition=edit.healthCondition.trim()&&edit.healthCondition.trim().length<=1000?'':'健康摘要必填且不能超过 1000 字';return !Object.values(errors).some(Boolean)}
async function saveBasic(){if(!validateBasic())return;saving.value=true;try{detail.value=await animalApi.patch(detail.value.id,{...edit,name:edit.name.trim(),species:edit.species.trim(),healthCondition:edit.healthCondition.trim(),color:edit.color?.trim()||null,version:detail.value.version});fill();ElMessage.success('已保存');await load()}finally{saving.value=false}}
async function appendImages(){if(!newImageTokens.value.length)return;saving.value=true;try{detail.value=await animalApi.addImages(detail.value.id,{imageTokens:newImageTokens.value});newImageTokens.value=[];ElMessage.success('图片已追加')}finally{saving.value=false}}
async function deleteImage(img){await ElMessageBox.confirm('确认删除该图片？','删除图片');saving.value=true;try{detail.value=await animalApi.deleteImage(detail.value.id,img.id)}finally{saving.value=false}}
async function addHealth(){const content=healthText.value.trim();if(!content){ElMessage.warning('健康记录不能为空');return}if(content.length>2000){ElMessage.warning('健康记录不能超过 2000 字');return}saving.value=true;try{await animalApi.addHealth(detail.value.id,{content});healthText.value='';health.value=await animalApi.health(detail.value.id)}finally{saving.value=false}}
async function stateAction(action,extra={}){saving.value=true;try{await animalApi.statusAction(detail.value.id,{action,version:detail.value.version,...extra});await refreshDetail();await load()}finally{saving.value=false}}
async function suspend(){const {value}=await ElMessageBox.prompt('暂停领养原因','暂停领养',{inputType:'textarea',inputValidator:v=>{const x=v?.trim()||'';return (!!x&&x.length<=500)||'暂停原因需为 1～500 字'}});await stateAction('SUSPEND_ADOPTION',{suspendReason:value.trim()})}
onMounted(load)
</script>
<style scoped>.photo-list{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}.photo-item{border:1px solid rgba(216,209,195,.9);padding:10px;border-radius:12px;background:rgba(255,253,248,.72);box-shadow:0 7px 16px rgba(23,61,57,.055)}.photo-item img{width:100%;height:108px;object-fit:cover;border-radius:8px}.photo-item span{font:10px var(--mono);display:block;margin-top:7px;color:var(--muted)}</style>
